#!/usr/bin/env python3
"""Independent velmora.media.v1 known-answer vectors (format decision §4.2).

Built only on pyca `cryptography` (OpenSSL HKDF, HMAC and ChaCha20-Poly1305),
never on velmora code, from the decision text alone. Regenerate with:

    python3 -I gen_vectors.py > vectors.txt

Every input is a fixed synthetic value; nothing here is a real key.
"""

import hashlib
import struct

from cryptography.hazmat.primitives import hashes, hmac
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305
from cryptography.hazmat.primitives.kdf.hkdf import HKDF, HKDFExpand

CHUNK = 65536
SIZES = [0, 1, 65535, 65536, 65537, 720896, 720897, 3 * 65536]
CTXS = [b"nntune/media", b"drive/media"]
RANDOM, VAULT, PUBLIC = 1, 2, 3

K_RANDOM = bytes(range(0x00, 0x20))
N_RANDOM = bytes(range(0xA0, 0xB0))
VAULT_DEDUPE_KEY = bytes(range(0x40, 0x60))
OPRF_OUTPUT = bytes(range(0x80, 0xC0))
# Full ciphertext is written out for objects up to this size; larger ones
# carry its SHA-256 (the Rust side compares the sealed bytes against it).
FULL_CT_MAX = 100


def plaintext(size):
    return bytes(i % 251 for i in range(size))


def hkdf(ikm, salt, info, length):
    return HKDF(algorithm=hashes.SHA256(), length=length, salt=salt, info=info).derive(ikm)


def hkdf_expand(prk, info, length):
    return HKDFExpand(algorithm=hashes.SHA256(), length=length, info=info).derive(prk)


def hkdf_extract(salt, ikm):
    h = hmac.HMAC(salt, hashes.SHA256())
    h.update(ikm)
    return h.finalize()


def mode_info(label, mode, ctx):
    return label + b"\x00" + bytes([mode]) + ctx


def content_info(label, ctx, size, digest):
    return label + b"\x00" + ctx + b"\x00" + struct.pack(">Q", size) + digest


def seal(key, mode, ctx, nonce, pt):
    prk = hkdf_extract(nonce, key)
    payload_key = hkdf_expand(prk, b"payload", 32)
    commitment = hkdf_expand(prk, mode_info(b"velmora.media.v1/commit", mode, ctx), 32)
    aead = ChaCha20Poly1305(payload_key)
    chunks = max(1, -(-len(pt) // CHUNK))
    out = bytearray(nonce + commitment)
    for i in range(chunks):
        last = i == chunks - 1
        chunk_nonce = i.to_bytes(11, "big") + (b"\x01" if last else b"\x00")
        out += aead.encrypt(chunk_nonce, pt[i * CHUNK:(i + 1) * CHUNK], None)
    return commitment, bytes(out)


def record(mode, ctx, size):
    pt = plaintext(size)
    digest = hashlib.sha256(pt).digest()
    fields = [("mode", str(mode)), ("ctx", ctx.decode()), ("p", str(size)), ("d", digest.hex())]
    if mode == RANDOM:
        key, nonce = K_RANDOM, N_RANDOM
    else:
        if mode == VAULT:
            h = hmac.HMAC(VAULT_DEDUPE_KEY, hashes.SHA256())
            h.update(content_info(b"velmora.media.v1/vault-K", ctx, size, digest))
            key = h.finalize()
            fields.append(("vault_dedupe_key", VAULT_DEDUPE_KEY.hex()))
        else:
            oprf_input = content_info(b"velmora.media.v1/public-K", ctx, size, digest)
            key = hkdf(OPRF_OUTPUT, None, b"velmora.media.v1/public-K", 32)
            fields.append(("oprf_input", oprf_input.hex()))
            fields.append(("oprf_output", OPRF_OUTPUT.hex()))
        nonce = hkdf(key, None, mode_info(b"velmora.media.v1/convergent-nonce", mode, ctx), 16)
    commitment, ct = seal(key, mode, ctx, nonce, pt)
    fields += [
        ("k", key.hex()),
        ("n", nonce.hex()),
        ("commitment", commitment.hex()),
        ("ct_len", str(len(ct))),
        ("ct_sha256", hashlib.sha256(ct).hexdigest()),
    ]
    if len(ct) <= FULL_CT_MAX:
        fields.append(("ct", ct.hex()))
    return "\n".join(f"{k}={v}" for k, v in fields)


def main():
    print("# velmora.media.v1 vectors: generated by gen_vectors.py (pyca cryptography).")
    print("# plaintext byte i = i % 251. Records are separated by blank lines.")
    for mode in (RANDOM, VAULT, PUBLIC):
        for ctx in CTXS:
            for size in SIZES:
                print()
                print(record(mode, ctx, size))


if __name__ == "__main__":
    main()
